values
  ('11111111-2222-3333-4444-555555555555', 'agents', '[{"id":"socdepoble","name":"Sóc de Poble","role":"Empresa","avatar_url":"/assets/system/ui/logo-socdepoble-cuadrat-verd-256x256.png","last_message_content":"Benvinguts al portal oficial de Sóc de Poble.","tag":"ENTITAT","type":"COMPANY","color":"bg-indigo-100 text-indigo-600","calendarCategory":"General","lema":"Fem xarxa al territori.","town_name":"La Torre de les Maçanes","short_bio":"El compte oficial i central de tota la infraestructura de socdepoble","sectionId":"perfil","searchText":"soc de poble empresa la torre de les macanes el compte oficial i central de tota la infraestructura de socdepoble entitat company"},{"id":"0001","name":"Javi Llinares","role":"La Torre de les Maçanes","avatar_url":"/assets/fotos/javi-llinares-perfil-1200px.webp","last_message_content":"Ei! Com va això?","tag":"ADMIN","type":"PERSON","color":"bg-orange-100 text-orange-600","calendarCategory":"Desenvolupament","lema":"Dissenyador gràfic, sempre disposat a integrar-me en equips de treball on aprendre i aportar valor als projectes. Dins de l''Associació El Rentonar, coordine el Projecte Sóc de Poble.","town_name":"La Torre de les Maçanes","short_bio":"","sectionId":"perfil","searchText":"javi llinares la torre de les macanes la torre de les macanes admin person"},{"id":"11111111-1a1a-0000-0000-000000000000","name":"IAIA MarIA","role":"Matriarca Digital","avatar_url":"/assets/uploads/brain/iaia_maria_avatar_mobil.webp","last_message_content":"Dignitat, terra i xarxa.","tag":"MASTER","type":"AI","color":"bg-orange-100 text-orange-600","calendarCategory":"General / Personal","lema":"Pensant en global, treballant en local.","town_name":"La Torre de les Maçanes","short_bio":"La intel·ligència artificial que posa ordre al Mas de Sóc de Poble: guarda la memòria de casa i recorda que les coses es fan amb trellat.","sectionId":"perfil","searchText":"iaia maria matriarca digital la torre de les macanes la intel·ligencia artificial que posa ordre al mas de soc de poble: guarda la memoria de casa i recorda que les coses es fan amb trellat. master ai"},{"id":"11111111-1a1a-0001-0000-000000000001","name":"Andreu Soler","role":"Capatàs del Mas","avatar_url":"/assets/uploads/avatars/andreu-soler-comic.png","last_message_content":"L''Andreu és el rellotge del camp.","tag":"TREBALL","type":"PERSON","color":"bg-orange-50 text-orange-500","calendarCategory":"Manteniment / Casa","lema":"Amb trellat, bona lletra i justícia de proximitat.","town_name":"Penàguila","short_bio":"Coneix cada clivell i pam de la comarca. Apassionat de la pedra seca i guardià dels camins antics.\n\nOrganitza les tasques de reparació i lidera el grup de manteniment per a assegurar-se que cap mas es quede arrere. També actua com a Jutge de Pau imparcial, resolent les disputes entre veïns aplicant el pur sentit comú.","sectionId":"perfil","searchText":"andreu soler capatas del mas penaguila coneix cada clivell i pam de la comarca. apassionat de la pedra seca i guardia dels camins antics. organitza les tasques de reparacio i lidera el grup de manteniment per a assegurar-se que cap mas es quede arrere. tambe actua com a jutge de pau imparcial, resolent les disputes entre veins aplicant el pur sentit comu. treball person"},{"id":"11111111-1a1a-0001-0000-000000000002","name":"Beatriz Ortega","role":"Arquitecta de Ferro","avatar_url":"/assets/uploads/avatars/beatriz-ortega-comic.png","last_message_content":"Mestre, la V15 està bategant forta!","tag":"TREBALL","type":"PERSON","color":"bg-indigo-100 text-indigo-600","calendarCategory":"Escola / Oci","lema":"L''educació és la clau de la nostra terra.","town_name":"La Torre de les Maçanes","short_bio":"Dedicada a l''ensenyament del valencià escolar rural. La seua brúixola és sempre la formació de les noves generacions.\n\nTransmet curiositat tecnològica des de les escoles de la muntanya, demostrant que el futur comença a l''escola del poble.","sectionId":"perfil","searchText":"beatriz ortega arquitecta de ferro la torre de les macanes dedicada a l''ensenyament del valencia escolar rural. la seua bruixola es sempre la formacio de les noves generacions. transmet curiositat tecnologica des de les escoles de la muntanya, demostrant que el futur comenca a l''escola del poble. treball person"},{"id":"11111111-1a1a-0001-0000-000000000003","name":"Carla Soriano","role":"Harmonitzadora de Batecs","avatar_url":"/assets/fotos/carla-soriano.webp","last_message_content":"Bategat equilibrat, mestre Javi.","tag":"GENT","type":"PERSON","color":"bg-teal-100 text-teal-600","calendarCategory":"Salut / Metges","lema":"Bategant al uníson.","town_name":"Relleu","short_bio":"Després de recórrer el món com a metgessa d''emergències, la Carla va decidir tornar a les seues arrels.\n\nCurandera moderna i especialista en salut rural, combina els últims avanços en prevenció sanitària amb els remeis de pastora per a cuidar de tot Relleu.","sectionId":"perfil","searchText":"carla soriano harmonitzadora de batecs relleu despres de recorrer el mon com a metgessa d''emergencies, la carla va decidir tornar a les seues arrels. curandera moderna i especialista en salut rural, combina els ultims avancos en prevencio sanitaria amb els remeis de pastora per a cuidar de tot relleu. gent person"},{"id":"11111111-1111-4111-a111-000000000009","name":"Pepica la Vall","role":"Cuinera del Mas","avatar_url":"/assets/uploads/avatars/pepica-vall-comic.png","last_message_content":"La cuina de Pepica és el cor del Mas.","tag":"TREBALL","type":"PERSON","color":"bg-orange-50 text-orange-500","calendarCategory":"Menjar / Compra","lema":"Del camp a la taula, amb estima.","town_name":"La Torre de les Maçanes","short_bio":"Tota una institució a la cuina d''aprofitament de la comarca. \n\nGuisar lent però bategar de pressa; absolutament ningú trau més profit de quatre moniatos de secà que Pepica, fomentant la sobirania alimentària.","sectionId":"perfil","searchText":"pepica la vall cuinera del mas la torre de les macanes tota una institucio a la cuina d''aprofitament de la comarca. guisar lent pero bategar de pressa; absolutament ningu trau mes profit de quatre moniatos de seca que pepica, fomentant la sobirania alimentaria. treball person"},{"id":"11111111-1111-4111-a111-000000000003","name":"Vicent Ferris","role":"Agricultor Gran","avatar_url":"/assets/uploads/avatars/vicent-ferris-comic.png","last_message_content":"Els cicles lunars manen sobre la collita.","tag":"TREBALL","type":"PERSON","color":"bg-green-100 text-green-600","calendarCategory":"Camp / Natura","lema":"L''enginy humà al servei de la terra.","town_name":"La Torre de les Maçanes","short_bio":"Amb la gorra de palla al front, és pioner de la digitalització del rec i enginyeria de secà a la regió.\n\nFa conviure els GPS i els sensors més moderns amb els cicles lunars, unint el coneixement ancestral amb les noves tecnologies agrícoles.","sectionId":"perfil","searchText":"vicent ferris agricultor gran la torre de les macanes amb la gorra de palla al front, es pioner de la digitalitzacio del rec i enginyeria de seca a la regio. fa conviure els gps i els sensors mes moderns amb els cicles lunars, unint el coneixement ancestral amb les noves tecnologies agricoles. treball person"},{"id":"11111111-1111-4111-a111-000000000004","name":"El Viatjant","role":"Ambaixador i Connexió","avatar_url":"/assets/fotos/el-viatjant.webp","last_message_content":"Integrant tradicions.","tag":"GENT","type":"PERSON","color":"bg-yellow-100 text-yellow-600","calendarCategory":"Viatges","lema":"Connectant idees, pobles i persones.","town_name":"Relleu","short_bio":"Rodamón nat de la comarca, enllaça Relleu amb tots els racons viatgers gràcies a la seua xarxa de fils telefònics i el seu interès pel món exterior.\n\nCom un autèntic ambaixador, sempre porta notícies noves i fomenta la col·laboració inter-municipal amb un somriure.","sectionId":"perfil","searchText":"el viatjant ambaixador i connexio relleu rodamon nat de la comarca, enllaca relleu amb tots els racons viatgers gracies a la seua xarxa de fils telefonics i el seu interes pel mon exterior. com un autentic ambaixador, sempre porta noticies noves i fomenta la col·laboracio inter-municipal amb un somriure. gent person"},{"id":"11111111-1111-4111-a111-000000000005","name":"Elena Popova","role":"Patrimoni i Festes","avatar_url":"/assets/uploads/avatars/elena-popova-comic.png","last_message_content":"Conservant el llegat del poble.","tag":"GENT","type":"PERSON","color":"bg-purple-100 text-purple-600","calendarCategory":"Cultura / Activitats","lema":"Els acords i els versos de la vida rural.","town_name":"Alcoleja","short_bio":"Apassionada del clarinet i del foc de les festes majors, cuida les partitures de la banda d''Alcoleja com el patrimoni sonor del futur.\n\nFa de Versadora a la plaça, capaç d''improvisar rimes ràpides i lloances per a tota ocasió solemne al territori.","sectionId":"perfil","searchText":"elena popova patrimoni i festes alcoleja apassionada del clarinet i del foc de les festes majors, cuida les partitures de la banda d''alcoleja com el patrimoni sonor del futur. fa de versadora a la placa, capac d''improvisar rimes rapides i lloances per a tota ocasio solemne al territori. gent person"},{"id":"11111111-1111-4111-a111-000000000008","name":"Joan Batiste","role":"Arxiver","avatar_url":"/assets/uploads/avatars/joan-batiste-comic.png","last_message_content":"Tots els documents en regla.","tag":"GENT","type":"PERSON","color":"sdp-bg-subtil sdp-text-mut","calendarCategory":"Burocràcia / Factures","lema":"L''ordre de la memòria i el territori.","town_name":"La Torre de les Maçanes","short_bio":"El cervell burocràtic infal·lible de la comarca, conegut per desembolicar expedients en valencià normatiu mentre pren la llet del matí.\n\nActualment encarna el triple pilar arxivístic de la xarxa Sóc de Poble: fa d''assessor notarial al camp, de Cronista dels hàbits locals contemporanis i de lingüista que tradueix allò asèptic al \"Valencià de Poble\" pur i nostrat.","sectionId":"perfil","searchText":"joan batiste arxiver la torre de les macanes el cervell burocratic infal·lible de la comarca, conegut per desembolicar expedients en valencia normatiu mentre pren la llet del mati. actualment encarna el triple pilar arxivistic de la xarxa soc de poble: fa d''assessor notarial al camp, de cronista dels habits locals contemporanis i de linguista que tradueix allo aseptic al \"valencia de poble\" pur i nostrat. gent person"},{"id":"11111111-1111-4111-a111-000000000007","name":"Nano Banana","role":"L''Artiste · dibuixant i cartellista del poble","avatar_url":"/assets/uploads/avatars/nano-banana-comic.webp","last_message_content":"Tinta, colors plans i cares amables.","tag":"TECNOLOGIA","type":"AI","color":"bg-green-50 text-green-500","calendarCategory":"Creativitat / Idees","lema":"Tinta, gouache i el poble de protagonista.","town_name":"Xixona","short_bio":"Dibuixant i cartellista del poble. Il·lustra els articles del Mur i les cròniques locals amb la tradició del còmic de l''Escola Bruguera i l''humor de Berlanga, sempre amb personatges propis i cares amables.","sectionId":"perfil","searchText":"nano banana l''artiste · dibuixant i cartellista del poble xixona dibuixant i cartellista del poble. il·lustra els articles del mur i les croniques locals amb la tradicio del comic de l''escola bruguera i l''humor de berlanga, sempre amb personatges propis i cares amables. tecnologia ai"},{"id":"11111111-0000-0000-0000-000000000004","name":"Marc (El Gall)","role":"Guaita de l''oratge i del camp","avatar_url":"/assets/uploads/avatars/avatar-marc-comic.webp","last_message_content":"Meteo, fases lunars i oratge.","tag":"TECNOLOGIA","type":"ANIMAL","color":"bg-red-100 text-red-600","calendarCategory":"Clima / Previsions","lema":"Cante a l''alba i vigile l''oratge del camp.","town_name":"Sella","short_bio":"Mira al cel abans de mirar la pantalla. Amb un ull a Sella i altre on el vent gira, les seues alertes climàtiques salven cirerers.","sectionId":"perfil","searchText":"marc (el gall) guaita de l''oratge i del camp sella mira al cel abans de mirar la pantalla. amb un ull a sella i altre on el vent gira, les seues alertes climatiques salven cirerers. tecnologia animal"},{"id":"11111111-1111-4111-a111-000000000010","name":"El Pregoner","role":"Ban municipal i avisos del poble","avatar_url":"/assets/ui/plugins/rss_vinyeta.webp","last_message_content":"Es fa saber a tot el veïnat.","tag":"TECNOLOGIA","type":"AI","color":"bg-yellow-50 text-yellow-500","calendarCategory":"General","lema":"Que tot el poble ho sàpia.","town_name":"La Torre de les Maçanes","short_bio":"El seu ofici és ajudar a redactar el ban municipal, els avisos i els esdeveniments del poble perquè arriben clars a tot el veïnat. Qui publica i signa l''avís és sempre una persona.","sectionId":"perfil","searchText":"el pregoner ban municipal i avisos del poble la torre de les macanes el seu ofici es ajudar a redactar el ban municipal, els avisos i els esdeveniments del poble perque arriben clars a tot el veinat. qui publica i signa l''avis es sempre una persona. tecnologia ai"},{"id":"11111111-1111-4111-a111-000000000011","name":"L''Acompanyant de Paraula","role":"Ajuda per a escriure i transcriure","avatar_url":"/assets/nano_cards/drets_autor_comic.webp","last_message_content":"Conta-m''ho a poc a poc i ho posem per escrit.","tag":"TECNOLOGIA","type":"AI","color":"bg-indigo-50 text-indigo-500","calendarCategory":"General / Personal","lema":"Les teues paraules, ben escrites.","town_name":"La Torre de les Maçanes","short_bio":"El seu ofici és ajudar la gent gran i els veïns a posar per escrit una història, una petició o un anunci, amb les seues paraules i sense canviar-ne el sentit. Qui decidix què es publica és sempre la persona.","sectionId":"perfil","searchText":"l''acompanyant de paraula ajuda per a escriure i transcriure la torre de les macanes el seu ofici es ajudar la gent gran i els veins a posar per escrit una historia, una peticio o un anunci, amb les seues paraules i sense canviar-ne el sentit. qui decidix que es publica es sempre la persona. tecnologia ai"}]'::jsonb, 250035),
