  ('11111111-2222-3333-4444-555555555555', 'events', '[{"date":"2023-01-29","time":"10:00","title":"2n Aplec pel Territori","type":"event","id":"aplec-2023","subtitle":"Nou Aplec, arrel de l''incendi d''aquest estiu","entradilla":"La Coordinadora d''Estudis Eòlics i l''Associació El Rentonar amb el Projecte Sóc de Poble hem organitzat a Benillup un nou Aplec pel Territori com a resposta a l''incendi que va assolar les nostres comarques en agost del 2022.","image_url":"/assets/events/aplec_2023_cartell.jpg","author_name":"Sóc de Poble","author_entity_id":"socdepoble","author_location":"La Torre de les Maçanes","author_avatar":"/assets/system/ui/logo-socdepoble-cuadrat-verd-256x256.png","sectionId":"events","searchText":"2n aplec pel territori la coordinadora d''estudis eolics i l''associacio el rentonar amb el projecte soc de poble hem organitzat a benillup un nou aplec pel territori com a resposta a l''incendi que va assolar les nostres comarques en agost del 2022. soc de poble event","sortDateValue":1674950400000}]'::jsonb, 250035),
